import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.oyZO4ogf.js";const u=JSON.parse('{"title":"ktor-svelte 1.0","description":"","frontmatter":{},"headers":[],"relativePath":"releases/1.0.md","filePath":"releases/1.0.md","lastUpdated":1794490612000}'),i={name:"releases/1.0.md"};function n(r,e,l,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="ktor-svelte-1-0" tabindex="-1">ktor-svelte 1.0 <a class="header-anchor" href="#ktor-svelte-1-0" aria-label="Permalink to &quot;ktor-svelte 1.0&quot;">​</a></h1><p>1.0 adds no headline feature. It is the release where the API stops moving, and where everything that was already there got tested harder than before.</p><h2 id="what-1-0-promises" tabindex="-1">What 1.0 promises <a class="header-anchor" href="#what-1-0-promises" aria-label="Permalink to &quot;What 1.0 promises&quot;">​</a></h2><p>From this release on, ktor-svelte follows semantic versioning:</p><ul><li>a patch release such as 1.0.1 only fixes bugs</li><li>a minor release such as 1.1.0 adds features and keeps your build working</li><li>only a major release can remove or rename something, and it comes with an <a href="./../migrations/">upgrade guide</a></li></ul><p>The promise covers the Kotlin API outside packages named <code>internal</code>, and the settings and tasks of the Gradle plugin.</p><h2 id="what-changed-on-the-way" tabindex="-1">What changed on the way <a class="header-anchor" href="#what-changed-on-the-way" aria-label="Permalink to &quot;What changed on the way&quot;">​</a></h2><p><strong>The API was cleaned up one last time.</strong> Enum constants use one casing, a deprecated alias is gone, and classes that were public by accident are closed. Most apps compile unchanged. The <a href="./../migrations/1.0">upgrade guide for 1.0</a> lists every step.</p><p><strong>A third example app.</strong> <a href="./../examples#showcase"><code>examples/showcase</code></a> is a team board with sign in, roles, an admin area, a database with migrations, file uploads, search, paging, themes and two languages. Building it and clicking through it is how most of the bugs below were found.</p><p><strong>Bugs fixed.</strong> Each of these was found by using ktor-svelte the way an app does, not by reading its code:</p><ul><li>A nullable property such as <code>val assignee: UserRef?</code> was typed as a second TypeScript type <code>UserRef2</code>. It is <code>UserRef | null</code> now.</li><li><code>call.messages</code> and <code>call.theme</code> failed with &quot;i18n is not configured&quot; while the app ran under <code>svelteDevAll</code>.</li><li>With <code>transport { compression() }</code>, precompressed pages and assets were compressed a second time on every request.</li><li>Text typed into an input with <code>use:field</code> before the page became interactive was wiped.</li><li>The dev proxy answered 502 to clients that offer an HTTP/2 upgrade, such as Java&#39;s <code>HttpClient</code>.</li><li>A compressed request body could unpack far beyond <code>maxApiBodySize</code>. The limit now also covers the unpacked size.</li><li>A path with a broken percent escape, and a <code>Host</code> header that cannot be parsed, answered 500. They answer 400 now.</li></ul><p><strong>The setup script is more careful.</strong> It does nothing until it has been downloaded completely, and it refuses a version that does not look like one.</p><h2 id="how-it-was-tested" tabindex="-1">How it was tested <a class="header-anchor" href="#how-it-was-tested" aria-label="Permalink to &quot;How it was tested&quot;">​</a></h2><ul><li><strong>End to end.</strong> Every example is built into a JAR and tested over HTTP. For the showcase that covers sessions, cookie flags, roles, uploads, paging, rate limits and data that survives a hard stop.</li><li><strong>In real browsers.</strong> The showcase JAR is driven by Playwright in Chromium, Firefox and WebKit: forms, uploads, downloads, both languages, themes and the Content-Security-Policy.</li><li><strong>Accessibility.</strong> Every page of the showcase passes the axe checks for WCAG 2.1 A and AA, in a light and in a dark theme.</li><li><strong>Development mode.</strong> A test starts <code>svelteDevAll</code>, edits a Svelte file and a Kotlin file, and checks that the open page updates and the app restarts.</li><li><strong>Every package manager.</strong> Bun, npm, pnpm and Yarn each install, build and test an example in CI.</li><li><strong>Upgrades.</strong> A project created by release 0.12.0 is switched to the current code and has to build, on every change.</li><li><strong>A pentest.</strong> About 150 hand-written requests against the showcase JAR: path traversal, redirects, the Host header, the origin check, request bodies, injection, access control, session cookies and sign in. The three weaknesses it found are in the list above. The <a href="./../security">security page</a> says what ktor-svelte protects and what it leaves to you.</li><li><strong>Static analysis.</strong> CodeQL scans the Kotlin, the TypeScript and the workflows on every pull request.</li></ul><h2 id="if-you-skipped-0-12" tabindex="-1">If you skipped 0.12 <a class="header-anchor" href="#if-you-skipped-0-12" aria-label="Permalink to &quot;If you skipped 0.12&quot;">​</a></h2><p>0.12 made IntelliJ a better place to work:</p><ul><li>Compiler errors and browser stack traces in the <code>svelteDevAll</code> console are links to the file and line.</li><li>New run configurations debug the frontend, and start the app with a debugger attached in one click.</li><li>New projects get their run configurations and live templates set up without a second command.</li></ul><h2 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h2><ol><li>Change the plugin version to <code>1.0.0</code>.</li><li>Run <code>./gradlew svelteSync</code>, and <code>./gradlew svelteGenerateTs</code> if you use <code>generateTs</code>. Commit what changed.</li><li>If the build does not compile, the <a href="./../migrations/1.0">upgrade guide for 1.0</a> has the step you need.</li></ol><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><ul><li>The built-in messages for <code>@JsonSchema</code> bounds are English. Write your own rule with <code>check</code> for other wording.</li><li>SvelteKit 3 does not load TypeScript 7 yet. Stay on TypeScript 6 in your frontend.</li><li>The dev proxy forwards HTTP only. Hot reload still works, because Vite&#39;s client connects to Vite directly.</li><li>There is no server-side rendering, by design. The <a href="./../reference/faq">FAQ</a> explains why and what to use instead.</li></ul><p>The full list of changes is in the <a href="./../changelog">changelog</a>.</p>',22)])])}const g=a(i,[["render",n]]);export{u as __pageData,g as default};
